// جلوگیری از کپی: منوی نگه‌داشتن، انتخاب متن و کپی/برش (جز در جای تایپ)
(function () {
  const typing = (e) => { const t = e.target; return !!(t && t.closest && t.closest("input, textarea, [contenteditable='true']")); };
  ["contextmenu", "selectstart", "copy", "cut", "dragstart"].forEach(ev => document.addEventListener(ev, (e) => { if (!typing(e)) e.preventDefault(); }, true));
})();
  const RAW = `AF:افغانستان|AL:آلبانی|DZ:الجزایر|AD:آندورا|AO:آنگولا|AG:آنتیگوا و باربودا|AR:آرژانتین|AM:ارمنستان|AU:استرالیا|AT:اتریش|AZ:جمهوری آذربایجان|BS:باهاما|BH:بحرین|BD:بنگلادش|BB:باربادوس|BY:بلاروس|BE:بلژیک|BZ:بلیز|BJ:بنین|BT:بوتان|BO:بولیوی|BA:بوسنی و هرزگوین|BW:بوتسوانا|BR:برزیل|BN:برونئی|BG:بلغارستان|BF:بورکینافاسو|BI:بوروندی|CV:کیپ‌ورد|KH:کامبوج|CM:کامرون|CA:کانادا|CF:جمهوری آفریقای مرکزی|TD:چاد|CL:شیلی|CN:چین|CO:کلمبیا|KM:کومور|CG:کنگو|CD:جمهوری دموکراتیک کنگو|CR:کاستاریکا|CI:ساحل عاج|HR:کرواسی|CU:کوبا|CY:قبرس|CZ:چک|DK:دانمارک|DJ:جیبوتی|DM:دومینیکا|DO:جمهوری دومینیکن|EC:اکوادور|EG:مصر|SV:السالوادور|GQ:گینه استوایی|ER:اریتره|EE:استونی|SZ:اسواتینی|ET:اتیوپی|FJ:فیجی|FI:فنلاند|FR:فرانسه|GA:گابن|GM:گامبیا|GE:گرجستان|DE:آلمان|GH:غنا|GR:یونان|GD:گرانادا|GT:گواتمالا|GN:گینه|GW:گینه بیسائو|GY:گویان|HT:هائیتی|HN:هندوراس|HU:مجارستان|IS:ایسلند|IN:هند|ID:اندونزی|IR:ایران|IQ:عراق|IE:ایرلند|IL:اسرائیل|IT:ایتالیا|JM:جامائیکا|JP:ژاپن|JO:اردن|KZ:قزاقستان|KE:کنیا|KI:کیریباتی|KP:کره شمالی|KR:کره جنوبی|KW:کویت|KG:قرقیزستان|LA:لائوس|LV:لتونی|LB:لبنان|LS:لسوتو|LR:لیبریا|LY:لیبی|LI:لیختن‌اشتاین|LT:لیتوانی|LU:لوکزامبورگ|MG:ماداگاسکار|MW:مالاوی|MY:مالزی|MV:مالدیو|ML:مالی|MT:مالت|MH:جزایر مارشال|MR:موریتانی|MU:موریس|MX:مکزیک|FM:میکرونزی|MD:مولداوی|MC:موناکو|MN:مغولستان|ME:مونته‌نگرو|MA:مراکش|MZ:موزامبیک|MM:میانمار|NA:نامیبیا|NR:نائورو|NP:نپال|NL:هلند|NZ:نیوزیلند|NI:نیکاراگوئه|NE:نیجر|NG:نیجریه|MK:مقدونیه شمالی|NO:نروژ|OM:عمان|PK:پاکستان|PW:پالائو|PA:پاناما|PG:پاپوآ گینه نو|PY:پاراگوئه|PE:پرو|PH:فیلیپین|PL:لهستان|PT:پرتغال|QA:قطر|RO:رومانی|RU:روسیه|RW:رواندا|KN:سنت کیتس و نویس|LC:سنت لوسیا|VC:سنت وینسنت و گرنادین|WS:ساموآ|SM:سن مارینو|ST:سائوتومه و پرنسیپ|SA:عربستان سعودی|SN:سنگال|RS:صربستان|SC:سیشل|SL:سیرالئون|SG:سنگاپور|SK:اسلواکی|SI:اسلوونی|SB:جزایر سلیمان|SO:سومالی|ZA:آفریقای جنوبی|SS:سودان جنوبی|ES:اسپانیا|LK:سری‌لانکا|SD:سودان|SR:سورینام|SE:سوئد|CH:سوئیس|SY:سوریه|TJ:تاجیکستان|TZ:تانزانیا|TH:تایلند|TL:تیمور شرقی|TG:توگو|TO:تونگا|TT:ترینیداد و توباگو|TN:تونس|TR:ترکیه|TM:ترکمنستان|TV:تووالو|UG:اوگاندا|UA:اوکراین|AE:امارات متحده عربی|GB:بریتانیا|US:ایالات متحده|UY:اروگوئه|UZ:ازبکستان|VU:وانواتو|VE:ونزوئلا|VN:ویتنام|YE:یمن|ZM:زامبیا|ZW:زیمبابوه|PS:فلسطین|VA:واتیکان`;

  const flag = (cc) => String.fromCodePoint(...[...cc].map(c => 0x1F1E6 + c.charCodeAt(0) - 65));
  const norm = (t) => t.replace(/ي/g, "ی").replace(/ك/g, "ک").replace(/[\u200c]/g, " ").trim();
  const fa = (n) => Number(n).toLocaleString("en-US");

  // ---- پارامترهای ارسالی از ربات
  const P = new URLSearchParams(location.search);
  const EPK = P.get("ep") || "";   // شناسه‌ی نسخه‌ی دیتا؛ با پاک شدن دیتای سرور عوض می‌شود و ذخیره‌ی محلیِ قدیمی دیگر بالا نمی‌آید
  const season = P.get("season") ? Number(P.get("season")) : null;
  const live = P.get("live") === "1";
  const locked = P.get("locked") === "1";
  const mine = (P.get("mine") || "").toUpperCase();
  const counts = {};
  const REALM = { owner: {}, area: {}, mine: null };   // کشورهای فتح‌شده ← فاتح، مساحت قلمرو (از /api/realm)
  const ownd = (c) => counts[c] || REALM.owner[c];       // «دارای بازیکن» یا «ضمیمه‌ی قلمروِ یک بازیکن»
  (P.get("counts") || "").split(",").forEach(x => {
    const [c, n] = x.split(".");
    if (c && n) counts[c.toUpperCase()] = Number(n);
  });
  // کشورهایی که همین الان بازیکن دارند (فقط برای کسی که هنوز کشور ندارد می‌آید)؛ در انتخاب نمایش داده نمی‌شوند
  const TAKEN = new Set((P.get("taken") || "").split(",").filter(Boolean).map(x => x.toUpperCase()));
  const listParam = (k, def) => (P.get(k) ? P.get(k).split(",") : def).map(x => x.toUpperCase());
  const PLUS = listParam("plus", ["US", "RU", "CN", "IR", "IL"]);
  const PREM = listParam("prem", ["FR", "GB", "JP", "KP", "IN"]);
  const tierOf = (code) => PLUS.includes(code) ? 0 : PREM.includes(code) ? 1 : 2;
  // رنگ حلقه‌ی دور پرچم من (همه‌ی صفحه‌ها): plus = پرمیوم پلاس، premium = پرمیوم، normal = عادی
  document.body.dataset.tier = mine && P.get("season") !== null ? ["plus", "premium", "normal"][tierOf(mine)] : "normal";
  const TIERS = ["💎 Premium Plus", "👑 Premium", "کشورهای عادی"];
  const TIER_BADGE = ["💎 Premium Plus", "👑 Premium"];
  // فقط وقتی سیزنی نیست یا سیزن فعلی است و قفل نشده، انتخاب ممکن است
  const readonly = season !== null && (!live || locked);
  const hideTaken = live && !readonly && TAKEN.size > 0;

  const countries = RAW.split("|").map(x => {
    const [code, name] = x.split(":");
    return { code, name, flag: flag(code), key: norm(name), n: counts[code] || 0 };
  }).sort((a, b) =>
    (season !== null ? tierOf(a.code) - tierOf(b.code) : 0) ||
    (b.code === mine) - (a.code === mine) ||
    (readonly ? b.n - a.n : 0) ||
    a.name.localeCompare(b.name, "fa"));

  const tg = window.Telegram.WebApp;
  tg.ready();
  tg.expand();
  tg.setHeaderColor("#0f1218");
  tg.setBackgroundColor("#0f1218");

  const el = (id) => document.getElementById(id);
  if (season !== null) {
    if (live) {
      el("title").textContent = "سیزن " + fa(season) + " 🟢";
      el("sub").textContent = locked ? (P.get("left") === "1" ? "شما از این فصل خارج شده‌اید؛ تا شروع سیزن بعد نمی‌توانید کشور بردارید." : P.get("other") ? "شما در دنیای " + fa(P.get("other")) + " کشور دارید؛ هر بازیکن فقط در یک دنیا بازی می‌کند. این دنیا را فقط می‌توانید ببینید." : "کشور شما در این سیزن ثبت شده است.") : "کشورت را برای این سیزن انتخاب کن و تأیید بزن." + (hideTaken ? " " + fa(Math.max(0, countries.length - TAKEN.size)) + " کشور آزاد است." : "");
    } else {
      el("title").textContent = "سیزن " + fa(season) + " (پایان‌یافته) 🏁";
      el("sub").textContent = "فهرست کشورها و تعداد بازیکن هر کشور در این سیزن.";
    }
  }
  if (mine) {
    const m = countries.find(c => c.code === mine);
    if (m) { el("badge").textContent = "کشور شما: " + m.name; el("badge").hidden = false; }
  }

  const list = el("list");
  const search = el("q");
  let selected = null;

  // big = پرچمِ بزرگِ صفحه‌ی خانه: تصویر وکتور (SVG، شفاف در هر اندازه)، بدون بریدن و با نسبت اصلیِ پرچم
  function flagNode(c, big) {
    const box = document.createElement("div");
    box.className = "flag";
    const img = new Image();
    img.alt = "";
    img.loading = big ? "eager" : "lazy";
    const lc = c.code.toLowerCase();
    const srcs = big ? ["https://flagcdn.com/" + lc + ".svg", "flags/" + lc + ".png", "https://flagcdn.com/w640/" + lc + ".png"]
                     : ["flags/" + lc + ".png", "https://flagcdn.com/w320/" + lc + ".png"];
    let step = 0;
    img.onerror = () => {
      step++;
      if (step < srcs.length) img.src = srcs[step];
      else { img.remove(); box.textContent = c.flag; }
    };
    if (big) {
      box.classList.add("fit");
      img.onload = () => {
        const r = (img.naturalWidth && img.naturalHeight) ? img.naturalWidth / img.naturalHeight : 1.5, maxW = 84, maxH = 56;
        const w = r >= maxW / maxH ? maxW : Math.round(maxH * r), h = r >= maxW / maxH ? Math.round(maxW / r) : maxH;
        box.style.width = w + "px"; box.style.height = h + "px";
      };
    }
    img.src = srcs[0];
    box.appendChild(img);
    return box;
  }

  function render() {
    const term = norm(search.value);
    const shown = countries.filter(c => (!term || c.key.includes(term)) && !(hideTaken && TAKEN.has(c.code)));
    list.innerHTML = "";
    if (!shown.length) {
      list.innerHTML = '<div class="empty">' + (hideTaken && !term ? "همه‌ی کشورها برداشته شده‌اند." : "کشوری پیدا نشد.") + "</div>";
      return;
    }
    let lastTier = -1;
    for (const c of shown) {
      const t = tierOf(c.code);
      if (season !== null && t !== lastTier) {
        lastTier = t;
        const h = document.createElement("div");
        h.className = "sec" + (t === 0 ? " s-plus" : t === 1 ? " s-premium" : "");
        h.textContent = TIERS[t];
        const small = document.createElement("small");
        small.textContent = "(" + fa(shown.filter(x => tierOf(x.code) === t).length) + ")";
        h.appendChild(small);
        list.appendChild(h);
      }
      const card = document.createElement("div");
      card.className = "c" + (c.code === mine ? " me" : "") +
        (season !== null && t < 2 ? " t-" + (t === 0 ? "plus" : "premium") : "");
      card.setAttribute("role", "option");
      card.tabIndex = 0;
      card.setAttribute("aria-selected", String(selected === c.code));
      if (readonly) card.setAttribute("aria-disabled", "true");

      card.appendChild(flagNode(c));
      if (season !== null && t < 2) {
        const tb = document.createElement("span");
        tb.className = "tier " + (t === 0 ? "plus" : "premium");
        tb.textContent = TIER_BADGE[t];
        card.appendChild(tb);
      }
      const name = document.createElement("div");
      name.className = "name";
      name.textContent = c.name;
      card.appendChild(name);

      if (readonly && P.get("nostats") !== "1") {
        const meta = document.createElement("div");
        meta.className = "meta";
        meta.textContent = c.n ? fa(c.n) + " بازیکن" : "بدون بازیکن";
        card.appendChild(meta);
      }
      if (c.code === mine) {
        const b = document.createElement("span");
        b.className = "mine";
        b.textContent = "کشور شما";
        card.appendChild(b);
      }
      if (!readonly) {
        const pick = () => choose(c);
        card.onclick = pick;
        card.onkeydown = (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); pick(); } };
      } else if (live) {   // دنیای فعال ولی قفل: به‌جای بی‌پاسخ ماندن، دلیل را بگو
        const why = () => toast(P.get("left") === "1" ? "شما از این فصل خارج شده‌اید؛ تا شروع سیزن بعد نمی‌توانید کشور بردارید."
          : P.get("other") ? "شما در دنیای " + fa(P.get("other")) + " کشور دارید؛ هر بازیکن فقط در یک دنیا بازی می‌کند."
          : "کشور شما در این سیزن ثبت شده است و قابل تغییر نیست.");
        card.onclick = why;
        card.onkeydown = (e) => { if (e.key === "Enter" || e.key === " ") { e.preventDefault(); why(); } };
      }
      list.appendChild(card);
    }
  }

  // ---------------- اطلاعات کشور برای صفحه‌ی تأیید (تقریبی؛ قابل ویرایش)
  const REGION = {
    "Africa": "DZ AO BJ BW BF BI CV CM CF TD KM CG CD CI DJ EG GQ ER SZ ET GA GM GH GN GW KE LS LR LY MG MW ML MR MU MA MZ NA NE NG RW ST SN SC SL SO ZA SS SD TZ TG TN UG ZM ZW",
    "Asia": "AF AM AZ BH BD BT BN KH CN GE IN ID IR IQ IL JP JO KZ KP KR KW KG LA LB MY MV MN MM NP OM PK PH QA SA SG LK SY TJ TH TL TR TM AE UZ VN YE PS",
    "Europe": "AL AD AT BY BE BA BG HR CY CZ DK EE FI FR DE GR HU IS IE IT LV LI LT LU MT MD MC ME NL MK NO PL PT RO RU SM RS SK SI ES SE CH UA GB VA",
    "N.America": "AG BS BB BZ CA CR CU DM DO SV GD GT HT HN JM MX NI PA KN LC VC TT US",
    "S.America": "AR BO BR CL CO EC GY PY PE SR UY VE",
    "Oceania": "AU FJ KI MH FM NR NZ PW PG WS SB TO TV VU",
  };
  const LANDLOCKED = new Set("AD AF AM AT AZ BY BT BO BW BF BI CF TD CZ SZ ET HU KZ KG LA LS LI LU MW ML MD MN NP NE MK PY RW SM RS SK SS TJ TM UG UZ VA ZM ZW".split(" "));
  const EXPOSED = new Set(("AF AL DZ AG AR AM AU AZ BS BD BB BZ BT BO BA BG KH CL CN CO KM CR HR CU DM DO EC SV FJ GE GR GD GT HT HN IS IN ID IR IT JM JP KI KG LB MG MV MH MU MX FM MM MZ NP NZ NI NR PK PW PA PG PE PH KN LC VC WS SB LK SY TJ TH TL TO TT TR TV US VU VE VN YE MA TN UZ KZ").split(" "));
  const NEIGHBORS = {
    DZ:"TN LY NE ML MR MA", AO:"CD CG ZM NA", BJ:"TG BF NE NG", BW:"ZA NA ZW ZM", BF:"ML NE BJ TG GH CI", BI:"RW TZ CD",
    CM:"NG TD CF CG GQ GA", CF:"TD SD SS CD CG CM", TD:"LY SD CF CM NG NE", CG:"GA CM CF CD AO", CD:"CG CF SS UG RW BI TZ ZM AO",
    CI:"LR GN ML BF GH", DJ:"ER ET SO", EG:"LY SD IL PS", GQ:"CM GA", ER:"SD ET DJ", SZ:"ZA MZ", ET:"ER DJ SO KE SS SD",
    GA:"GQ CM CG", GM:"SN", GH:"CI BF TG", GN:"GW SN ML CI LR SL", GW:"SN GN", KE:"SO ET SS UG TZ", LS:"ZA", LR:"SL GN CI",
    LY:"TN DZ NE TD SD EG", MW:"TZ MZ ZM", ML:"DZ NE BF CI GN SN MR", MR:"DZ ML SN", MA:"DZ", MZ:"TZ MW ZM ZW ZA SZ",
    NA:"AO ZM BW ZA", NE:"DZ LY TD NG BJ BF ML", NG:"BJ NE TD CM", RW:"UG TZ BI CD", SN:"MR ML GN GW GM", SL:"GN LR",
    SO:"ET KE DJ", ZA:"NA BW ZW MZ SZ LS", SS:"SD ET KE UG CD CF", SD:"EG LY TD CF SS ET ER", TZ:"KE UG RW BI CD ZM MW MZ",
    TG:"GH BF BJ", TN:"DZ LY", UG:"SS KE TZ RW CD", ZM:"CD TZ MW MZ ZW BW NA AO", ZW:"ZA BW ZM MZ",
    AF:"PK IR TM UZ TJ CN", AM:"GE AZ TR IR", AZ:"RU GE AM IR TR", BD:"IN MM", BT:"IN CN", BN:"MY", KH:"TH LA VN",
    CN:"RU MN KP VN LA MM IN BT NP PK AF TJ KG KZ", GE:"RU AZ AM TR", IN:"PK CN NP BT BD MM", ID:"MY PG TL",
    IR:"IQ TR AM AZ TM AF PK", IQ:"TR IR KW SA JO SY", IL:"LB SY JO EG PS", JO:"SY IQ SA IL PS", KZ:"RU CN KG UZ TM",
    KP:"CN RU KR", KR:"KP", KW:"IQ SA", KG:"KZ UZ TJ CN", LA:"MM CN VN KH TH", LB:"SY IL", MY:"TH ID BN", MN:"RU CN",
    MM:"BD IN CN LA TH", NP:"IN CN", OM:"AE SA YE", PK:"IN AF IR CN", QA:"SA", SA:"JO IQ KW QA AE OM YE",
    SY:"TR IQ JO IL LB", TJ:"UZ KG CN AF", TH:"MM LA KH MY", TL:"ID", TR:"GR BG GE AM AZ IR IQ SY", TM:"KZ UZ AF IR",
    AE:"SA OM", UZ:"KZ KG TJ AF TM", VN:"CN LA KH", YE:"SA OM", PS:"IL EG JO",
    AL:"ME MK GR", AD:"FR ES", AT:"DE CZ SK HU SI IT CH LI", BY:"RU UA PL LT LV", BE:"NL DE LU FR", BA:"HR RS ME",
    BG:"RO RS MK GR TR", HR:"SI HU RS BA ME", CZ:"DE PL SK AT", DK:"DE", EE:"RU LV", FI:"SE NO RU",
    FR:"BE LU DE CH IT MC ES AD", DE:"DK PL CZ AT CH FR LU BE NL", GR:"AL MK BG TR", HU:"AT SK UA RO RS HR SI", IE:"GB",
    IT:"FR CH AT SI SM VA", LV:"EE LT RU BY", LI:"CH AT", LT:"LV BY PL RU", LU:"BE DE FR", MD:"RO UA", MC:"FR",
    ME:"HR BA RS AL", NL:"BE DE", MK:"RS BG GR AL", NO:"SE FI RU", PL:"DE CZ SK UA BY LT RU", PT:"ES",
    RO:"UA MD BG RS HU", RU:"NO FI EE LV LT PL BY UA GE AZ KZ CN MN KP", SM:"IT", RS:"HU RO BG MK ME BA HR",
    SK:"CZ PL UA HU AT", SI:"IT AT HU HR", ES:"PT FR AD", SE:"NO FI", CH:"DE FR IT AT LI", UA:"BY RU PL SK HU RO MD",
    GB:"IE", VA:"IT",
    AR:"CL BO PY BR UY", BZ:"MX GT", BO:"BR PY AR CL PE", BR:"UY AR PY BO PE CO VE GY SR", CA:"US", CL:"PE BO AR",
    CO:"VE BR PE EC PA", CR:"NI PA", EC:"CO PE", SV:"GT HN", GT:"MX BZ HN SV", GY:"VE BR SR", HT:"DO", HN:"GT SV NI",
    MX:"US GT BZ", NI:"HN CR", PA:"CR CO", PY:"BO BR AR", PE:"EC CO BR BO CL", SR:"GY BR", US:"CA MX", UY:"AR BR",
    VE:"CO BR GY", DO:"HT", PG:"ID",
  };
  const regionOf = (code) => { for (const k in REGION) if (REGION[k].split(" ").includes(code)) return k; return ""; };

  // ---------------- قوانین بازی: در هر سیزن پیش از انتخاب کشور باید همه‌ی بندها خوانده و قبول شوند
  const RULES = [
    "هر بازیکن فقط یک حساب و در هر سیزن فقط یک کشور دارد. ساخت حساب دوم یا بازی به‌جای دیگری ممنوع است.",
    "کشور انتخاب‌شده در همین سیزن برای شما ثبت می‌شود. اگر کشور را ترک کنید می‌توانید در همان سیزن دوباره کشور بردارید؛ ولی هر ۱۴ روز فقط یک بار ترک ممکن است (جز خروج رایگانِ اول).",
    "با ترک کشور، دارایی‌های آن (پول، انبار، ساختمان‌ها، ارتش) برای اولین کسی که آن کشور را بردارد می‌ماند؛ تا وقتی کسی آن را برنداشته، اگر خودتان همان کشور را دوباره بردارید دارایی‌ها مال خودتان است.",
    "اگر کشور خود را ترک کنید و بازیکن دیگری آن کشور را بردارد، دیگر نمی‌توانید با آن کشور بازی کنید و همه‌ی دارایی‌های شما به همان بازیکنِ جدید می‌رسد؛ در این صورت فقط می‌توانید کشور دیگری که آزاد است انتخاب کنید.",
    "سوءاستفاده از باگ، تقلب، هماهنگی پنهان برای دور زدن قوانین یا خرابکاری در اقتصاد و بازار ممنوع است و به جریمه یا حذف از بازی می‌انجامد.",
    "به سایر بازیکنان و ادمین‌ها احترام بگذارید؛ توهین، تهدید و محتوای نامناسب در بیانیه‌ها و گفتگوها ممنوع است.",
    "خرید پک‌ها و اقلام فروشگاه (کارگر، پول، اشتراک و ...) با واریز کارت‌به‌کارت و ارسال رسید واقعی انجام می‌شود و بعد از تأیید ادمین اعمال می‌شود. ارسال رسید جعلی یا تکراری ممنوع و مستوجب مسدود شدن است؛ قیمت‌ها ممکن است تغییر کند و فقط روی سفارش‌های بعدی اثر دارد. اقلام خریداری‌شده (مثل کارگر) مال حساب خودتان است و با ترک کشور به دیگری نمی‌رسد، و پس از اعمال، بازگشت وجه ممکن نیست.",
    "جنگ، اتحاد، وام و معامله فقط از راه‌های خودِ بازی انجام می‌شود و تعهدات ثبت‌شده (پیمان‌ها و وام‌ها) لازم‌الاجرا هستند.",
    "تصمیم ادمین درباره‌ی تخلف‌ها، جبران خسارت و تنظیم‌های بازی قطعی است و ممکن است برای تعادل بازی تغییراتی اعمال شود.",
    "ادامه‌ی بازی در این سیزن به معنی پذیرفتن همه‌ی بندهای بالاست.",
  ];
  (function setupRules() {
    const ol = el("crlist"), chk = el("crchk"), hint = el("crhint"), wrap = el("crwrap"), bar = el("crbar"), lab = el("crlab"), box = el("crules");
    if (!ol || !chk) return;
    RULES.forEach(t => { const li = document.createElement("li"); li.textContent = t; ol.appendChild(li); });
    const HINT0 = "⬇ ابتدا قوانین را تا انتها بخوانید (داخل کادر بالا را پایین بکشید)";
    const atEnd = () => ol.scrollTop + ol.clientHeight >= ol.scrollHeight - 6;
    const progress = () => {
      const max = ol.scrollHeight - ol.clientHeight;
      const p = max <= 0 ? 1 : Math.min(1, ol.scrollTop / max);
      bar.style.width = Math.round(p * 100) + "%";
      wrap.classList.toggle("atend", atEnd());
    };
    const unlock = () => {
      if (!chk.disabled) return;
      chk.disabled = false; lab.classList.remove("locked");
      hint.textContent = "✓ تا انتها خواندید؛ اکنون تیک قبول را بزنید."; hint.className = "rhint ok";
      lab.classList.add("pulse"); setTimeout(() => lab.classList.remove("pulse"), 1800);
    };
    ol.addEventListener("scroll", () => { progress(); if (atEnd()) unlock(); }, { passive: true });
    chk.addEventListener("change", () => { el("cok").setAttribute("aria-disabled", chk.checked ? "false" : "true"); });
    // لمس چک‌باکس/دکمه‌ی غیرفعال: به کاربر نشان بده باید قوانین را بخواند
    const nudge = () => {
      if (!chk.disabled) return;
      box.scrollIntoView({ behavior: "smooth", block: "center" });
      wrap.classList.remove("shake"); void wrap.offsetWidth; wrap.classList.add("shake");
      hint.classList.add("flash"); setTimeout(() => hint.classList.remove("flash"), 1200);
      toast("اول قوانین را تا انتها بخوانید (داخل کادر پایین بکشید).");
      if (tg.HapticFeedback && tg.HapticFeedback.notificationOccurred) tg.HapticFeedback.notificationOccurred("warning");
    };
    lab.addEventListener("click", e => { if (chk.disabled) { e.preventDefault(); nudge(); } });
    el("cok").addEventListener("click", () => { if (chk.disabled) nudge(); else if (!chk.checked) toast("تیک «خواندم و قبول می‌کنم» را بزنید."); });
    window.__rulesReset = () => {   // هر بار که صفحه‌ی تأیید باز می‌شود از نو
      chk.checked = false; chk.disabled = true; lab.classList.add("locked"); el("cok").setAttribute("aria-disabled", "true");
      hint.textContent = HINT0; hint.className = "rhint";
      ol.scrollTop = 0; progress();
      setTimeout(() => { progress(); if (atEnd()) unlock(); }, 50);   // اگر قوانین کوتاه بود و اسکرول نداشت
    };
  })();

  function showConfirm(c) {
    selected = c.code;
    if (window.__rulesReset) window.__rulesReset();
    if (tg.HapticFeedback) tg.HapticFeedback.selectionChanged();
    const t = tierOf(c.code);
    el("chead").className = "cbox head" + (season !== null && t === 0 ? " t-plus" : season !== null && t === 1 ? " t-premium" : "");
    el("cflag").innerHTML = ""; el("cflag").appendChild(flagNode(c));
    el("cname").textContent = c.name;
    { const cs = el("csym"); cs.innerHTML = ""; const si = window.symbolImg && window.symbolImg(c.code, "sym lg"); if (si) cs.appendChild(si); }
    el("cregion").textContent = regionOf(c.code);
    const cap = capitalOf(c.code);
    el("ccap").textContent = cap; el("ccaprow").hidden = !cap;
    el("cpop").textContent = POP[c.code] ? fa(POP[c.code]) + " نفر" : "—";
    el("csea").textContent = LANDLOCKED.has(c.code) ? "ندارد" : "دارد";
    const nb = (NEIGHBORS[c.code] || "").split(" ").filter(Boolean);
    el("cnbn").textContent = fa(nb.length);
    el("cnbl").textContent = nb.map(x => (countries.find(y => y.code === x) || {}).name).filter(Boolean).join("، ");
    el("cnbl").hidden = !nb.length;
    el("chaz").textContent = EXPOSED.has(c.code) ? "در معرض" : "کم‌خطر";
    el("cok").textContent = "بله، " + c.name + " را انتخاب می‌کنم";
    ["top", "tabs", "list", "sw", "nav", "homeview", "mapview"].forEach(id => { el(id).hidden = true; });
    el("cview").hidden = false;
    window.scrollTo(0, 0);
    if (window.__rulesReset) window.__rulesReset();   // بعد از نمایش (اندازه‌ها معلوم‌اند)
  }
  function closeConfirm() { selected = null; el("cview").hidden = true; setView("list"); }
  el("cback").onclick = closeConfirm;
  el("cmenu").onclick = closeConfirm;
  el("cgoal").onclick = () => openGoals();
  el("cok").onclick = () => confirm();

  function choose(c) { showConfirm(c); }

  // دکمه‌ی کیبوردی: sendData کار می‌کند. دکمه‌ی شیشه‌ای / منو / پروفایل: تلگرام sendData را قبول نمی‌کند،
  // پس انتخاب با لینک ?start= به ربات می‌رسد و مینی‌اپ بسته می‌شود.
  // نسخه‌ی وب (بدون تلگرام): انتخاب/ترک کشور مستقیم با سرور بازی انجام می‌شود
  async function sendWeb(obj) {
    const TKW = P.get("tk") || "", SRV = (P.get("api") || P.get("ja") || "").replace(/\/+$/, "");
    if (!TKW || !SRV) { alert("نشست نامعتبر است. در ربات /web بزنید و دوباره وارد شوید."); return; }
    try {
      const ctl = new AbortController(), t = setTimeout(() => ctl.abort(), 35000);
      const r = await fetch(SRV + "/api/webaction", { method: "POST", signal: ctl.signal,
        headers: { "Content-Type": "application/json", "X-Token": TKW },
        body: JSON.stringify(Object.assign({ ep: P.get("ep") || "" }, obj)) }).finally(() => clearTimeout(t));
      let d = {}; try { d = await r.json(); } catch (e) { /* پاسخ خالی */ }
      if (!r.ok) throw new Error(d.fa || "خطا در ارتباط با سرور.");
      if (d.msgs && d.msgs.length) alert(d.msgs.join("\n\n"));
      if (d.url) location.href = d.url; else location.reload();
    } catch (e) { alert(e && e.name === "AbortError" ? "پاسخی از سرور نیامد؛ دوباره تلاش کنید." : (e.message || "خطا")); }
  }
  function sendBot(obj) {
    if (tg.isWebShim) return sendWeb(obj);
    const viaLink = tg.initDataUnsafe && tg.initDataUnsafe.query_id && P.get("bot");
    if (viaLink) {
      const pl = (obj.action === "leave" ? "l_" : "p_") + obj.season + "_" + (obj.code || "") + (P.get("ep") ? "_" + P.get("ep") : "") + (obj.rules ? "_r" : "");
      if (tg.openTelegramLink) tg.openTelegramLink("https://t.me/" + P.get("bot") + "?start=" + pl);
      setTimeout(() => { if (tg.close) tg.close(); }, 500);
    } else tg.sendData(JSON.stringify(Object.assign({ ep: P.get("ep") || "" }, obj)));
  }

  function confirm() {
    const c = countries.find(x => x.code === selected);
    if (!c) return;
    const chk = el("crchk");
    if (chk && !chk.checked) return;   // پیام را شنوده‌ی نشان‌دادن راهنما نشان می‌دهد
    sendBot({ country: c.name, code: c.code, season, rules: 1 });
  }

