        const vis = Math.asin(Math.min(1, half)) + 0.22;   // کمی حاشیه برای کشورهای بزرگ که مرکزشان بیرون کادر است
        for (const c in PROV_DATA) {
          const pt = pointOf(c);
          if (!pt) continue;
          const d = d3.geoDistance(pt, center);
          if (c === tg || d < vis) cand.push([c === tg ? -1 : d, c]);
        }
