    if (hud) { cs.position = "fixed"; cs.left = "0"; cs.top = "0"; cs.width = W + "px"; cs.height = H + "px"; if (FLAT && zoom < zminNow()) zoom = zminNow(); }
    else { cs.position = ""; cs.left = ""; cs.top = ""; cs.width = ""; cs.height = ""; }
    ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
