  // ---------------- بافت واقعی زمین (کوه، جنگل، بیابان…) روی کره
  // اول vendor/earth.jpg (با get_assets.py)، بعد CDN. اگر هیچ‌کدام نشد، رنگ ساده‌ی قبلی.
  const TEX_URLS = [
    "vendor/earth.jpg",
    "https://cdn.jsdelivr.net/npm/three-globe/example/img/earth-day.jpg",
  ];
  const TEX = { ok: false, w: 0, h: 0, d: null };
  const TEX_GAMMA = 0.78;   // <1 = روشن‌تر؛ اقیانوس‌های بافت ناسا خیلی تیره‌اند
  const OFF = document.createElement("canvas"), OFFC = OFF.getContext("2d");
