  // ---------------- ارتباطات (بیانیه‌ها)
  // بدون سرور، فقط بیانیه‌های خودِ کاربر دیده می‌شود (بدون نمونه) و روی همین دستگاه ذخیره می‌شود.
  // اتصال به بیانیه‌های واقعی نیاز به ذخیره‌ی آن‌ها در دیتابیس ربات دارد.
  // سهمیه‌ی روزانه‌ی بیانیه بر اساس دسته‌ی کشور: Premium Plus، Premium، عادی
  const COMM_QUOTA = [8, 5, 3];
  const cmQuota = () => REMOTE ? CMR.quota : COMM_QUOTA[tierOf(mine)];
  const cmNotif = () => REMOTE ? !!CMR.notif : !!CM.notif;
  const CM_OK = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M8 12.5l2.8 2.8L16 9.5"/></svg>';
  const CM_NO = '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M5.7 5.7l12.6 12.6"/></svg>';
  const CMK = "ow_comm_" + (season === null ? "x" : season) + "_" + (mine || "") + "_" + EPK;
  const CM = (() => {
    const d = { votes: {}, posts: [], day: "", used: 0, notif: 1 };
    try { return Object.assign(d, JSON.parse(localStorage.getItem(CMK) || "{}")); } catch (e) { return d; }
  })();
  // حالت واقعی: اگر ربات آدرس سرور (api) و توکن (tk) را داده باشد، بیانیه‌ها از سرور می‌آیند و برای همه مشترک‌اند.
  // آدرس سرور بازی (https). اگر ربات آن را در آدرس نگذاشته باشد (مثلاً مینی‌اپ از منو/لینک مستقیم باز شود)، این مقدار به کار می‌رود.
  const DEFAULT_API = "";
  const API = (P.get("api") || DEFAULT_API).replace(/\/+$/, ""), TK = P.get("tk") || "", INIT = tg.initData || "";
  const REMOTE_CFG = !!(API && (TK || INIT));  // سرور تنظیم شده؟ (با tk یا با initData امضاشده‌ی تلگرام)
  let REMOTE = REMOTE_CFG;                    // سرور همین الان در دسترس است؟ با قطع اتصال خاموش می‌شود (حالت محلی) و با وصل‌شدن دوباره روشن
  let srvTimer = 0, BOOTED = false, srvUp = null, downEl = null;
