  function cmCloseSheet() { el("comask").hidden = true; el("cosheet").hidden = true; }
  function cmCount() {
    const n = el("cota").value.trim().length;
    el("cocnt").textContent = n + " / 280"; el("cosend").disabled = n < 5;
  }
  function cmOpenSheet() {
    if (cmLeft() <= 0) { toast("سهمیه‌ی بیانیه‌ی امروز تمام شده است."); return; }
    el("cota").value = ""; cmCount();
    el("cosub").textContent = cmLeft() + " بیانیه‌ی دیگر امروز می‌توانی منتشر کنی";
    el("comask").hidden = false; el("cosheet").hidden = false;
  }
  el("cota").oninput = cmCount;
  el("cosend").onclick = async () => {
    const text = el("cota").value.trim();
    if (text.length < 5 || cmLeft() <= 0) return;
    if (REMOTE) {
      el("cosend").disabled = true;
      try {
        const d = await cmApi("/api/statement", { text });
        CMR.items.unshift(cmFix(d.item)); CMR.left = d.left; CMR.quota = d.quota;
      } catch (e) { toast(e.message); cmCount(); return; }
    } else {
      CM.used++; CM.day = cmDay();
      CM.posts.unshift({ id: "p" + Date.now(), ts: Date.now(), text: text.slice(0, 280) });
      CM.posts = CM.posts.slice(0, 30);
      cmSave();
    }
    cmCloseSheet(); buildComm(); window.scrollTo(0, 0);
    toast("بیانیه منتشر شد ✅");
  };
  document.querySelectorAll("#cotabs .cmtab").forEach(b => { b.onclick = () => { cmtab = b.dataset.t; buildComm(); }; });
  el("copost").onclick = cmOpenSheet;
  el("conote").onclick = async () => {
    const on = !cmNotif();
    if (REMOTE) { try { await cmApi("/api/notif", { on }); CMR.notif = on ? 1 : 0; } catch (e) { toast(e.message); return; } }
    else { CM.notif = on ? 1 : 0; cmSave(); }
    buildComm(); toast(on ? "اعلان بیانیه‌ها روشن شد" : "اعلان بیانیه‌ها خاموش شد");
  };
