  const elBPower = (k, lv) => EL.PW.BENF ? Math.max(1, Math.ceil(elCostRaw(k, lv) / EL.PW.BDIV)) : 0;
  const elReserved = (lv, pend) => Object.keys(pend || {}).reduce((a, k) => a + (elAll[k] ? elBPower(k, lv[k] || 0) : 0), 0);
  const elAvail = (lv, pend) => elSupply(lv) - elDemand(lv) - elReserved(lv, pend);
