  // اجرای یک درخواست؛ اگر تا رسیدن پاسخ درخواست تازه‌تری داده شده یا پنجره بسته شده، این پاسخ دور ریخته می‌شود
  async function arRun(load, draw, back, retry) {
    const my = ++arReq;
    arMsg("در حال دریافت…");
    try {
      const d = await load();
      if (my !== arReq) return;
      draw(d);
    } catch (e) {
      if (my !== arReq) return;
      arFail(e.message, back, retry);
    }
  }
