  async function govFetch() {
    if (!REMOTE || document.hidden) return;
    try { window.OWGovData = await cmApi("/api/gov"); } catch (e) { /* بدون داده */ }
    try { window.OWEvData = await cmApi("/api/events"); evBanner(); } catch (e) { /* بدون داده */ }
  }
  // رویداد در جریانِ کشور زیر نوار رضایت مردم در صفحه‌ی خانه
  function evBanner() {
    const sat = el("hsats"); if (!sat || !sat.parentNode) return;
    let b = el("hevent");
    if (!b) { b = document.createElement("div"); b.id = "hevent"; b.style.cssText = "margin:8px 0 0;padding:8px 11px;border-radius:12px;font-size:12px;line-height:1.7;background:rgba(0,0,0,.28);border:1px solid #e07a28"; sat.parentNode.insertBefore(b, sat.nextSibling); }
    const act = (window.OWEvData && window.OWEvData.active) || [];
    const last = (window.OWEvData && window.OWEvData.items && window.OWEvData.items[0]) || null;
    const x = act[0] || (last && Date.now() / 1000 - last.start < 6 * 3600 ? last : null);
    b.hidden = !x;
    if (x) { b.textContent = x.icon + " " + x.name + (x.active ? " (در جریان)" : "") + (x.note ? " — " + x.note : ""); b.style.borderColor = x.kind === "good" ? "#4fae7b" : x.kind === "crisis" ? "#c75454" : "#e07a28"; }
  }
  function govOf(code) {
    const g = window.OWGovData; if (!g || !g.all) return "—";
    const o = (g.options || []).find(x => x.key === g.all[code]);
    return o ? o.icon + " " + o.name : "—";
  }
  setTimeout(govFetch, 2500); setInterval(govFetch, 60000);

  function hudRefresh() {
    if (!hudOn()) return;
    const h = FH[FLAT ? "flat" : "globe"]; if (!h) return;
    const R = h.R, c = byCode[mine], code = target(), tc = byCode[code] || c;
    if (!c) return;
    const own = code === mine;
    if (!h.g && R.avFor !== mine) { R.avFor = mine; R.av.innerHTML = ""; R.av.appendChild(flagNode(c)); }
    R.nm.firstChild.textContent = c.name;
    R.nm.lastChild.textContent = "رتبه: " + (RM ? RM.rank : GAME.level) + " ★";
  }
  setInterval(() => { if (hudOn()) hudRefresh(); }, 1500);

  // ---------------- انتخاب دنیا (سیزن) — صفحه‌ی اول
  // ربات برای هر سیزن یک پارامتر می‌فرستد: w<شماره>=live_mine_locked_ends_counts_taken
  const WORLDS = [];
  // کشورهای برداشته‌شده‌ی هر دنیا: t<شماره>=IR,RU,... (هر دنیا بازیکنان و کشورهای مستقل خودش را دارد)
  const WTAKEN = {};
  for (const [k, v] of P.entries()) {
    const mt = /^t(\d+)$/.exec(k);
    if (mt) WTAKEN[mt[1]] = v;
  }
  for (const [k, v] of P.entries()) {
    const m = /^w(\d+)$/.exec(k);
    if (!m) continue;
    const [lv, mi, lk, ed, cn, tk, pl, lf] = v.split("_");
    WORLDS.push({ n: Number(m[1]), live: lv === "1", mine: (mi || "").toUpperCase(), locked: lk === "1", left: lf === "1",
                  ends: Number(ed) || 0, counts: cn || "", taken: Number(tk) || 0, players: Number(pl) || 0 });
  }
  WORLDS.sort((a, b) => b.n - a.n);
  const LOBBY = season === null && P.get("lobby") === "1" && WORLDS.length > 0;
  const SEASON_KEYS = ["season", "live", "mine", "locked", "ends", "counts", "view", "nostats"];
  // داده‌های شخصیِ سیزن فعلی؛ هنگام رفتن به دنیای دیگر نباید همراه بروند
  const PERSONAL_KEYS = ["ev", "rt", "rk", "rm", "fx", "lnext", "left"];

  function openWorld(w) {
    const Q = new URLSearchParams(location.search);
    SEASON_KEYS.forEach(k => Q.delete(k));
    PERSONAL_KEYS.forEach(k => Q.delete(k));
    Q.delete("taken"); Q.delete("other");   // مال دنیای قبلی است؛ هر دنیا فهرست خودش را دارد
    Q.set("season", w.n);
    if (w.live) {
      Q.set("live", "1");
      if (w.ends) Q.set("ends", w.ends);
      if (w.locked) Q.set("locked", "1");
      if (w.left) Q.set("left", "1");   // از همین دنیا خارج شده؛ بدون این، صفحه‌ی دنیا دلیل قفل را نمی‌داند
      if (WTAKEN[w.n] && !w.mine) Q.set("taken", WTAKEN[w.n]);
      // بازیکن در دنیای دیگری کشور دارد: فقط یک دنیا می‌شود بازی کرد
      const ow = (!w.mine && w.locked) ? WORLDS.find(x => x.live && x.mine) : null;
      if (ow) Q.set("other", ow.n);
    } else if (w.counts) {
      Q.set("counts", w.counts.replace(/-/g, ","));
    } else if (w.players) {
      Q.set("nostats", "1");  // آمار این سیزن در آدرس جا نشد
    }
    if (w.mine) Q.set("mine", w.mine);
    location.replace(location.pathname + "?" + Q.toString() + location.hash);
  }
  function goLobby() {
    const Q = new URLSearchParams(location.search);
    SEASON_KEYS.forEach(k => Q.delete(k));
    location.replace(location.pathname + "?" + Q.toString() + location.hash);
  }

  function worldCard(w) {
    const b = document.createElement("button");
    b.type = "button";
    b.className = "world " + (w.live ? "live" : "past");
    const g = document.createElement("div"); g.className = "wg"; g.textContent = w.live ? "🌐" : "🏁";
    const t = document.createElement("div"); t.className = "wt";
    const n = document.createElement("div"); n.className = "wn"; n.textContent = "World " + w.n;
    const m = document.createElement("div"); m.className = "wm";
    const total = countries.length;
    const mc = w.mine && byCode[w.mine] ? " · کشور شما: " + byCode[w.mine].name : "";
    if (w.live) {
      const free = Math.max(0, total - w.taken);
      m.textContent = fa(free) + " کشور خالی از " + fa(total) + mc;
    } else {
      m.textContent = "پایان‌یافته · " + fa(w.players) + " بازیکن" + mc;
    }
    t.append(n, m);
    const go = document.createElement("div"); go.className = "go"; go.textContent = "‹";
    b.append(g, t, go);
    b.onclick = () => { if (tg.HapticFeedback) tg.HapticFeedback.selectionChanged(); openWorld(w); };
    return b;
  }

  function showLobby() {
    view = "lobby";
    ["homeview", "mapview", "list", "sw", "top", "tabs", "nav", "scoutview", "rankview", "notifview", "commview", "ecoview", "infraview", "armyview", "warview", "shopview", "marketview", "loanview", "dipview"].forEach(id => { el(id).hidden = true; });
    el("lobbyview").hidden = false;
    el("wlive").innerHTML = ""; el("wpast").innerHTML = "";
    WORLDS.filter(w => w.live).forEach(w => el("wlive").appendChild(worldCard(w)));
    const past = WORLDS.filter(w => !w.live);
    past.forEach(w => el("wpast").appendChild(worldCard(w)));
    el("wpastbox").hidden = !past.length;
    tg.MainButton.hide();
    syncBack();
    window.scrollTo(0, 0);
  }

  // ---------------- دیده‌بان (فهرست همه‌ی دنیاها، بدون نیاز به کشور)
  const START_CEASEFIRE_DAYS = 3;   // آتش‌بسِ آغاز فصل (از شروع سیزن)
  const DAILY_CEASEFIRE_END = 12;   // بعد از آن، هر روز تا این ساعت (به وقت تهران) آتش‌بس است
  const SD = Math.max(1, qn("sd", 30));  // طول هر فصل به روز (از ربات)
  let stab = "all";
  const STAB_LABELS = { all: "همه", run: "در جریان", reg: "ثبت‌نام", end: "پایان‌یافته" };

  function scoutWorlds() {
    if (WORLDS.length) return WORLDS;
    if (season === null) return [];
    // آدرس بدون پارامتر w: فقط همین سیزن
    const pl = Object.values(counts).reduce((a, b) => a + b, 0);
    return [{ n: season, live, mine, locked, ends: endsAt ? Math.round(endsAt / 1000) : 0,
              counts: "", taken: Object.keys(counts).length, players: pl }];
  }
  const wstatus = (w) => !w.live ? "end" : (w.ends ? "run" : "reg");
  function tehranHour() {
    try {
      return Number(new Intl.DateTimeFormat("en-GB", { hour: "2-digit", hour12: false, timeZone: "Asia/Tehran" }).format(new Date())) % 24;
    } catch (e) { return new Date().getHours(); }
  }
  const GLOBE_SVG = '<svg viewBox="0 0 24 24" fill="none" stroke="#f6e3b0" stroke-width="1.7" stroke-linecap="round"><circle cx="12" cy="12" r="9"/><ellipse cx="12" cy="12" rx="4" ry="9"/><path d="M3 12h18M4.6 7.5h14.8M4.6 16.5h14.8"/></svg>';

  function scoutInfo(w, now) {
    const st = wstatus(w);
    if (st === "end") return { st, badge: ["پایان‌یافته", "end"], sub: "پایان‌یافته · " + w.players + " بازیکن", pct: 100 };
    if (st === "reg") return { st, badge: ["ثبت‌نام باز", "reg"], sub: "ثبت‌نام باز · " + w.taken + " کشور", pct: 0 };
    const started = (w.ends - SD * 86400) * 1000;
    const day = Math.max(1, Math.floor((now - started) / 86400000) + 1);
    let badge = null;
    const cfLeft = started + START_CEASEFIRE_DAYS * 86400000 - now;
    if (cfLeft > 0) badge = ["آتش‌بس آغاز فصل · " + dur(cfLeft), "cf"];
    else if (tehranHour() < DAILY_CEASEFIRE_END) badge = ["آتش‌بس تا " + DAILY_CEASEFIRE_END + ":00", "cf"];
    return { st, badge, sub: "روز " + day + " · " + w.taken + " کشور", pct: null };
  }

  function scoutCard(w, now) {
    const f = scoutInfo(w, now);
    const b = document.createElement("button");
    b.type = "button"; b.className = "sw " + (f.st === "end" ? "past" : "live");
    b.innerHTML = '<div class="sic wc' + (w.n % 8) + '">' + GLOBE_SVG + '</div>' +
      '<div class="sbody"><div class="stop"><span class="sn"></span></div><div class="ssub"></div>' +
      '<div class="sbar"><i></i></div></div><span class="sgo">‹</span>';
    b.querySelector(".sn").textContent = "World " + w.n;
    if (f.badge) {
      const sp = document.createElement("span"); sp.className = "sb " + f.badge[1]; sp.textContent = f.badge[0];
      b.querySelector(".stop").appendChild(sp);
    }
    b.querySelector(".ssub").textContent = f.sub;
    if (f.pct === null) b.querySelector(".sbar").style.display = "none";
    else b.querySelector(".sbar i").style.width = f.pct.toFixed(1) + "%";
    b.onclick = () => scoutOpen(w);
    return b;
  }

  function scoutOpen(w) {
    if (tg.HapticFeedback) tg.HapticFeedback.selectionChanged();
    if (season === w.n) { setView(hasMine ? "map" : "list"); return; }
    openWorld(w);
  }
  function scoutBack() {
    if (scoutPrev === "lobby") showLobby();
    else if (hasMine) setView(scoutPrev && scoutPrev !== "scout" ? scoutPrev : "home");
    else if (LOBBY) showLobby();
    else if (CAN_LOBBY) goLobby();
    else setView("list");
  }

  function buildScout() {
    const now = Date.now(), all = scoutWorlds().slice().sort((a, b) => b.n - a.n);
    const c = hasMine ? byCode[mine] : null;
    el("sgrp").hidden = !c;
    el("savatar").innerHTML = "";
    if (c) {
      el("savatar").appendChild(flagNode(c)); el("savatar").firstChild.classList.add("lg");
      const lv = document.createElement("div"); lv.className = "lvl"; lv.textContent = RM ? RM.rank : GAME.level; el("savatar").appendChild(lv);
    }
    const cnt = { all: all.length, run: 0, reg: 0, end: 0 };
    all.forEach(w => { cnt[wstatus(w)]++; });
    if (stab === "end" && !cnt.end) stab = "all";
    el("stabs").innerHTML = "";
    ["all", "run", "reg", "end"].filter(k => k !== "end" || cnt.end).forEach(k => {
      const t = document.createElement("button"); t.type = "button"; t.className = "stab" + (stab === k ? " on" : "");
      t.innerHTML = "<span>" + STAB_LABELS[k] + "</span><small>" + cnt[k] + "</small>";
      t.onclick = () => { stab = k; buildScout(); };
      el("stabs").appendChild(t);
    });
    const list = el("slist"); list.innerHTML = "";
    const shown = all.filter(w => stab === "all" || wstatus(w) === stab);
    if (!shown.length) list.innerHTML = '<div class="empty">' + (all.length ? "دنیایی در این بخش نیست." : "هنوز دنیایی برای نمایش نیست.") + "</div>";
    shown.forEach(w => list.appendChild(scoutCard(w, now)));
    updateBadges();
  }
  el("savatar").onclick = () => setView("map");
  el("scup").onclick = () => setView("rank");
  el("sbell").onclick = () => setView("notif");
  el("sgoal").onclick = () => openGoals();
  el("shelp").onclick = () => toast("دیده‌بان: همه‌ی دنیاها · نیروها محرمانه است");
  el("lscout").onclick = () => setView("scout");
  setInterval(() => { if (view === "scout") buildScout(); }, 30000);

  // دکمه‌ی برگشتِ تلگرام: از فهرست کشورها به انتخاب دنیا
  const CAN_LOBBY = !LOBBY && P.get("lobby") === "1" && WORLDS.length > 0;
  function syncBack() {
    if (!tg.BackButton) return;
    if (view === "rank" || view === "notif" || view === "eco" || view === "infra" || view === "army" || view === "war" || view === "shop" || view === "market" || view === "loan" || view === "dip" || view === "scout" || CAN_LOBBY) tg.BackButton.show(); else tg.BackButton.hide();
  }
  if (tg.BackButton) tg.BackButton.onClick(() => {
    if (view === "scout") scoutBack();
    else if (view === "rank" || view === "notif" || view === "eco" || view === "infra" || view === "army" || view === "war" || view === "shop" || view === "market" || view === "loan" || view === "dip") setView("home");
    else if (CAN_LOBBY) goLobby();
  });

  if (P.get("ns") === "1") showNoSeason();
  else if (!P.has("season") && P.get("lobby") !== "1") {
    // باز شدن مستقیم (دکمه‌ی «مینی‌اپ» پروفایل ربات / لینک ساده) بدون اطلاعات سیزن: فهرست کشورها نشان داده نمی‌شود
    el("noseason").querySelector("p").textContent =
      "اگر ادمین هنوز سیزن را شروع نکرده، منتظر بمانید تا از طریق ربات خبر بدهیم. اگر سیزن شروع شده، ربات را باز کنید، /start بزنید و از دکمه‌ی داخل ربات وارد شوید.";
    showNoSeason();
  }
  ecoLoad();
  const pv = P.get("view");
  const bootView = () => { BOOTED = true; if (window.__splashReady) window.__splashReady(); realmLoad(); if (LOBBY) showLobby(); else setView(pv === "map" && hasMine ? "map" : pv === "comm" && hasMine ? "comm" : pv === "eco" && hasMine ? "eco" : pv === "infra" && hasMine ? "infra" : pv === "list" ? "list" : hasMine ? "home" : "list"); };
  // Do not open the game panel from URL params alone: when the server is reachable, confirm first that this user
  // still owns the country (old chat buttons keep an old mine=XX link after a data reset).
  const runBoot = () => {
    // تا جواب سرور نیامده فهرست کشورها زیرِ لودینگ دیده نشود (لودینگ بعد از ~۱۰ ثانیه کنار می‌رود؛ اگر سرور کند باشد بازیکنِ دارای کشور «انتخاب کشور» می‌دید)
    if (REMOTE && mine && live && !LOBBY && hasMine) ["list", "sw", "top"].forEach((id) => { el(id).hidden = true; });
    if (REMOTE && mine && live && !LOBBY) cmApi("/api/session").then(bootView, (e) => {
      if (!el("noseason").hidden) return;
      if (e && e.net) { showStaleLink("net"); srvUp = () => { if (!BOOTED) { el("noseason").hidden = true; runBoot(); } }; }
      else bootView();
    });
    else bootView();
  };
  // عضویت اجباری «قبل از هر چیز»: تا لودینگ تمام نشده و جواب عضویت نیامده، بازی بوت نمی‌شود (هر دکمه/لینکی که کاربر با آن آمده باشد).
  // عضو نبود ← صفحه‌ی عضویت جای بازی را می‌گیرد. بررسیِ سرور هم مستقل است: همه‌ی مسیرهای API تا عضو نشود «join» می‌دهند.
  // همین بررسی، لینک قدیمی را هم می‌شناسد: شناسه‌ی نسخه‌ی دیتای سرور (ep) با لینک نخواند ← صفحه‌ی اصلیِ تازه باز می‌شود.
  (async () => {
    if (JAPI && (INIT || TK)) {
      let d = null;
      try { d = await sysGet("/api/join"); } catch (e) { /* قطعی را بقیه‌ی کد مدیریت می‌کند؛ API خودش بدون عضویت جواب نمی‌دهد */ }
      if (d && d.ok === false) { showJoin(d); return; }
      if (d && d.ep && d.ep !== EPK && await staleRecover("stale")) return;
    }
    runBoot();
  })();
